package org.apache.commons.lang3;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.equals(CharSequence, CharSequence)
 */
public class StringUtils_equals_TriageGen1Test {

    @Test
    public void testEquals_SameReference() {
        String s = "test";
        assertTrue("Should return true for same reference", StringUtils.equals(s, s));
        assertTrue("Should return true for both null", StringUtils.equals(null, null));
    }

    @Test
    public void testEquals_OneNull() {
        assertFalse("Should return false when first is null", StringUtils.equals(null, "test"));
        assertFalse("Should return false when second is null", StringUtils.equals("test", null));
    }

    @Test
    public void testEquals_BothStrings_Equal() {
        assertTrue("Should return true for equal strings", StringUtils.equals("abc", "abc"));
    }

    @Test
    public void testEquals_BothStrings_NotEqual() {
        assertFalse("Should return false for unequal strings", StringUtils.equals("abc", "def"));
        assertFalse("Should return false for different lengths", StringUtils.equals("abc", "abcd"));
    }

    @Test
    public void testEquals_MixedTypes_Equal() {
        // Using StringBuilder to test the CharSequence branch that is not both String
        CharSequence cs1 = "abc";
        CharSequence cs2 = new StringBuilder("abc");

        // Based on the code: 
        // if (cs1 instanceof String && cs2 instanceof String) is false here.
        // It falls through to CharSequenceUtils.regionMatches
        assertTrue("Should return true for equal CharSequences of different types", 
                StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_MixedTypes_NotEqual() {
        CharSequence cs1 = "abc";
        CharSequence cs2 = new StringBuilder("abd");
        assertFalse("Should return false for unequal CharSequences", StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_MixedTypes_DifferentLengths() {
        CharSequence cs1 = "abc";
        CharSequence cs2 = new StringBuilder("abcd");
        assertFalse("Should return false for different lengths in CharSequence branch", 
                StringUtils.equals(cs1, cs2));
    }

    @Test
    public void testEquals_EmptySequences() {
        assertTrue("Both empty strings should be equal", StringUtils.equals("", ""));
        assertTrue("Both empty StringBuilders should be equal", 
                StringUtils.equals("", new StringBuilder("")));
        assertFalse("One empty, one not", StringUtils.equals("", "a"));
    }

    @Test
    public void testEquals_CaseSensitivity() {
        // The method uses regionMatches with matchAsciiCase = false (case-sensitive)
        assertFalse("Should be case sensitive", StringUtils.equals("abc", "ABC"));
    }
}
